#include &lt;stdio.h&gt;

using ull = unsigned long long int;

ull get_out(ull base, ull power)
{
    const ull MAX = 1'000'000'000ULL + 1;
    ull ret = 1;

    while (power != 0) {
        if (ret &gt; MAX) {
            return MAX;
        }

        if ((power % 2) == 1) {
            ret *= base;
            --power;
            continue;
        }

        power &gt;&gt;= 1;
        if (base * base &gt; MAX) {
            return MAX;
        }
        base *= base;
    }

    return ret;
}

ull get_out(ull base, ull power, ull mod)
{
    ull ret = base;

    if (power == 0) {
        return 1;
    } else if ((power % 2) == 1) {
        return ((ret % mod) * get_out(base, power - 1, mod)) % mod;
    } else {
        return (get_out((base * base) % mod, power &gt;&gt; 1, mod) % mod);
    }

    return ret;
}

int main(void)
{
    int t;
    scanf("%d", &t);
    while (t--) {
        ull x, y, z;
        scanf("%llu%llu%llu", &x, &y, &z);

        ull cmp = get_out(x, y);
        ull out = get_out(x, y, z * 1000);
        ull integer = out / z;
        ull decimal = out % z;
        decimal *= 1000;
        decimal /= z;
        if (cmp == out) {
            printf("%llu.%03llu\n", integer, decimal);
        } else {
            printf("%03llu.%03llu\n", integer, decimal);
        }
    }
}

