        {
            auto key = edges[j];
            int i = j - 1;
            while (i &gt;= 0 && edges[i] &gt; key)
            {
                edges[i + 1] = edges[i];
                --i;
            }
            edges[i + 1] = key;
        }

        for (int i = 0; i &lt; n - 1; ++i)
        {
            _min_val += edges[i];                  // Min MST: 가장 작은 N-1개
            _max_val += edges[(i * (i + 1)) / 2];  // Max MST: 삼각수 인덱스
        }

        printf("%lld %lld\n", _min_val, _max_val);
        delete[] edges;
    }
