#include &lt;stdio.h&gt;

using ll = long long int;

ll x1, x2, y1, y2, k;

ll _MIN(ll a, ll b)
{
    return (a &lt; b) ? a : b;
}

ll _MAX(ll a, ll b)
{
    return (a &gt; b) ? a : b;
}

ll all()
{
    return 2*k*k + 2 * k + 1;
}

ll exclude(ll from, ll to)
{
    if(y1 &gt; k) return 0;
    if(from &gt; to) return 0;

    to = _MIN(to, k - y1 + 1);
    if(from &gt; to) return 0;

    auto n = to - from + 1;

    return (n * (2*(k - y1 + 1) - from - to)) &gt;&gt; 1;
}

ll include()
{
    if(y2 + 1 &gt; k) return 0;

    ll l_rsc = 0, r_rsc = 0;

    if(y2 + 1 - k &lt; x1)
    {
        auto consumed = (-x1 + 1) + (y2 + 1);
        l_rsc = _MAX(0, k - consumed);
    }
    if(x2 &lt; k - y2 - 1)
    {
        auto consumed = (x2 + 1) + (y2 + 1);
        r_rsc = _MAX(0, k - consumed);
    }

    ll ret = 0;

    ll sum_x = l_rsc - r_rsc + x1 + x2;
    ll mid = (sum_x &gt;= 0) ? (sum_x / 2) : ((sum_x - 1) / 2);

    ll left_to = _MIN(x2, mid);
    if (x1 &lt;= left_to && l_rsc &gt; 0)
    {
        ll effective_to = _MIN(left_to, l_rsc + x1 - 1);
        if (x1 &lt;= effective_to)
        {
            ll n = effective_to - x1 + 1;
            ll first = l_rsc - x1 + x1;
            ll last = l_rsc - effective_to + x1;
            ret += (n * (first + last)) &gt;&gt; 1;
        }
    }

    ll right_from = _MAX(x1, mid + 1);
    if (right_from &lt;= x2 && r_rsc &gt; 0)
    {
        ll effective_from = _MAX(right_from, x2 - r_rsc + 1);
        if (effective_from &lt;= x2)
        {
            ll n = x2 - effective_from + 1;
            ll first = r_rsc + effective_from - x2;
            ll last = r_rsc + x2 - x2;
            ret += (n * (first + last)) &gt;&gt; 1;
        }
    }

    return ret;
}

int main(void)
{
    int t;
    scanf("%d", &t);
    while(t--)
    {
        scanf("%lld%lld%lld%lld%lld", &x1, &x2, &y1, &y2, &k);

        ll common_range = _MIN(-x1, x2);
        ll outer_range = _MAX(-x1, x2);

        printf("%lld\n",
            all()
            - exclude(0, 0)
            - 2 * exclude(1, common_range)
            - exclude(common_range + 1, outer_range)
            + include()
        );
    }
}

