        for(int i = 0; i &lt; n; ++i) scanf("%d", &a[i]), a[i] &lt;&lt;= 1;

        bool is_inf = false;
        for(int i = 0; i &lt; n - 1; ++i)
        {
            if(a[i] == a[i + 1])
            {
                is_inf = true;
                break;
            }
        }
        if(is_inf)
        {
            printf("-1\n");
            continue;
        }

        int cand_scaled[99];
        for(int i = 0; i &lt; n; ++i) cand_scaled[i] = a[i];

        // 삽입 정렬
        for(int j = 1; j &lt; n; ++j)
        {
            int key = cand_scaled[j];
            int i = j - 1;
            while(i &gt;= 0 && cand_scaled[i] &gt; key)
            {
                cand_scaled[i + 1] = cand_scaled[i];
                --i;
            }
            cand_scaled[i + 1] = key;
        }

        // 정렬된 고유값 사이 중간점 후보
        for(int i = 0; i &lt; n - 1; ++i)
            cand_scaled[i + n] = ((ll)cand_scaled[i] + cand_scaled[i + 1]) / 2;

        int _max_val = -1;
        int iter = (2 * n) - 1;

        auto get_cnt_root = [&a, n](int y0) -&gt; int
        {
            int cnt = 0;
            for(int i = 0; i &lt; n - 1; ++i)
            {
                int low  = (a[i] &lt; a[i + 1]) ? a[i] : a[i + 1];
                int high = (a[i] &lt; a[i + 1]) ? a[i + 1] : a[i];

                bool cond =
                    ((a[i] &lt; a[i + 1]) && (y0 &gt;= low && y0 &lt; high)) ||
                    ((a[i] &gt; a[i + 1]) && (y0 &gt; low && y0 &lt;= high));

                if(cond) ++cnt;
            }
            if(y0 == a[n - 1]) ++cnt;
            return cnt;
        };

        for(int i = 0; i &lt; iter; ++i)
        {
            auto curr = get_cnt_root(cand_scaled[i]);
            _max_val = (_max_val &gt; curr) ? _max_val : curr;
        }

        printf("%d\n", _max_val);
    }
}

