#include &lt;stdio.h&gt;
using ull = unsigned long long int;

// 소프트웨어 popcount (Hamming Weight 알고리즘)
ull popcount_sw(ull x) {
    x = x - ((x &gt;&gt; 1) & 0x5555555555555555ULL); // 2비트 단위로 합산
    x = (x & 0x3333333333333333ULL)
      + ((x &gt;&gt; 2) & 0x3333333333333333ULL);      // 4비트 단위로 합산
    x = (x + (x &gt;&gt; 4)) & 0x0F0F0F0F0F0F0F0FULL; // 8비트 단위로 합산
    return (x * 0x0101010101010101ULL) &gt;&gt; 56;    // 바이트 합을 최상위로
}

int main(void)
{
    int t; scanf("%d", &t);
    for (int tc = 1; tc &lt;= t; ++tc)
    {
        ull n; scanf("%llu", &n);

        ull p       = popcount_sw(n);  // N의 켜진 비트 수
        ull odd_cnt = 1ULL &lt;&lt; p;       // 홀수 이항계수 수 = 2^p
        ull ans     = (n + 1ULL) - odd_cnt;

        printf("#%d %llu\n", tc, ans);
    }
}


