Tip대안 판정: 전체 XOR의 popcount



실전에서 popcount(a[1] ^ a[2] ^ ... ^ a[n]) == n 조건으로 판정하는 풀이도 AC를 받는다. 이는 모든 MSB가 서로 다를 때 XOR이 비트를 보존하는 성질에 의존하는데, 엄밀한 동치 증명은 쉽지 않으므로 MSB 직접 비교가 더 안전하다.

7 전체 풀이 코드
#include &lt;stdio.h&gt;

int a[100001];
int px[100001];

int main(void)
{
    int t;
    scanf("%d", &t);
    while (t--) {
        int n;
        scanf("%d", &n);
        px[0] = 0;
        for (int i = 1; i &lt;= n; ++i) {
            scanf("%d", &a[i]);
            px[i] = px[i - 1] ^ a[i];
        }

        // Case 1: N &gt;= 61 → 비둘기집 원리로 답 = 1
        if (n &gt;= 61) {
            puts("1");
            continue;
        }

        // Case 2: 모든 인접 MSB가 다르면 → 답 = -1
        bool all_distinct = true;
        for (int i = 2; i &lt;= n; ++i) {
            if ((31 - __builtin_clz(a[i])) == (31 - __builtin_clz(a[i - 1]))) {
                all_distinct = false;
                break;
            }
        }
        if (all_distinct) {
            puts("-1");
            continue;
        }

        // Case 3: N &lt;= 60 → O(N^3) 브루트포스
        int best = 100000;
        for (int i = 1; i &lt;= n; ++i) {
            for (int j = i; j &lt;= n; ++j) {
                int L = px[j] ^ px[i - 1];
                for (int k = j + 1; k &lt;= n; ++k) {
                    int R = px[k] ^ px[j];
                    if (L &gt; R) {
                        int cost = k - i - 1;
                        if (cost &lt; best) {
                            best = cost;
                        }
                        if (best == 1) {
                            goto done;
                        }
                    }
                }
            }
        }
        done:
        printf("%d\n", best);
    }
    return 0;
}

